package org.apache.commons.math3.genetics;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.apache.commons.math3.exception.OutOfRangeException;
import org.apache.commons.math3.exception.util.LocalizedFormats;
import org.apache.commons.math3.util.FastMath;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ElitisticListPopulation_ElitisticListPopulation_TriageGen2Test {

    @Test
    public void testConstructorWithLimitAndRate() {
        int populationLimit = 10;
        double elitismRate = 0.1;

        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, elitismRate);

        assertNotNull(population);
        assertEquals(populationLimit, population.getBufferSize());
        assertEquals(elitismRate, population.getElitismRate(), 1e-10);
    }

    @Test
    public void testConstructorWithChromosomes() {
        int populationLimit = 5;
        double elitismRate = 0.2;
        List<Chromosome> chromosomes = new ArrayList<>();
        // Mocking Chromosome is complex due to interface, 
        // but we assume a basic implementation or mock if available.
        // Since we cannot create a real Chromosome easily without its implementation details,
        // we use a minimal mock-like approach if the environment allows, 
        // or assume the class handles the list.

        // For the sake of this unit test, we assume Chromosome is an interface 
        // and we provide a dummy implementation.
        class DummyChromosome implements Chromosome {
            @Override
            public double getFitness() { return 1.0; }
            @Override
            public Chromosome replicate() { return this; }
        }

        chromosomes.add(new DummyChromosome());

        ElitisticListPopulation population = new ElitisticListPopulation(chromosomes, populationLimit, elitismRate);

        assertNotNull(population);
        assertEquals(populationLimit, population.getBufferSize());
        assertEquals(elitismRate, population.getElitismRate(), 1e-10);
    }

    @Test
    public void testSetAndGetElitismRate() {
        int populationLimit = 10;
        double initialRate = 0.1;
        double newRate = 0.5;

        ElitisticListPopulation population = new ElitisticListPopulation(populationLimit, initialRate);
        assertEquals(initialRate, population.getElitismRate(), 1e-10);

        population.setElitismRate(newRate);
        assertEquals(newRate, population.getElitismRate(), 1e-10);
    }
}
